import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import HeaderPrimary from 'flarum/forum/components/HeaderPrimary';
app.initializers.add('spottersturkey-header-menu', () => {
  extend(HeaderPrimary.prototype, 'items', function (items) {
    let links = [];
    try {
      const settings = app.forum.attribute('spottersturkey-header-menu.links');
      if (settings) {
        links = JSON.parse(settings);
      }
    } catch (e) {
      links = [];
    }
    if (links && links.length > 0) {
      const menuHtml = m("div", {
        className: "CustomHeaderMenu"
      }, links.map((link, i) => {
        const hasSublinks = link.sublinks && link.sublinks.length > 0;
        const mainContent = [link.icon ? m("i", {
          className: link.icon
        }) : null, m("span", null, link.label), hasSublinks ? m("i", {
          className: "fas fa-chevron-down CustomHeaderMenu-caret"
        }) : null];
        if (hasSublinks) {
          return m("div", {
            className: "CustomHeaderMenu-dropdown"
          }, m("a", {
            className: "CustomHeaderMenu-item",
            href: link.url || 'javascript:void(0)'
          }, mainContent), m("div", {
            className: "CustomHeaderMenu-dropdownMenu"
          }, link.sublinks.map(sublink => m("a", {
            className: "CustomHeaderMenu-dropdownItem",
            href: sublink.url,
            target: sublink.target || '_self'
          }, sublink.icon ? m("i", {
            className: sublink.icon
          }) : null, sublink.label))));
        }
        return m("a", {
          className: "CustomHeaderMenu-item",
          href: link.url,
          target: link.target || '_self',
          title: link.label
        }, mainContent);
      }));

      // Add as the first item in HeaderPrimary (which puts it right after the logo, before the search box)
      items.add('customHeaderMenu', menuHtml, 100);
    }
  });
});